# Alternative patterns
alt_height_patterns = [
    r'standing height to be ([\d.]+) centimeters',
    r'height, (?:recorded|documented|listed) as ([\d.]+) centimeters',
    r'height is ([\d.]+) centimeters',
]

heroes_height = {}
